import json, time

def emit_emf(pipeline, rows_processed, rows_failed, duration_ms):
    # EMF: one structured log line -> metrics + queryable log
    emf = {
        "_aws": {
            "Timestamp": int(time.time() * 1000),
            "CloudWatchMetrics": [{
                "Namespace": "ETL",
                "Dimensions": [["Pipeline", "Env"]],
                "Metrics": [
                    {"Name": "RowsProcessed", "Unit": "Count"},
                    {"Name": "RowsFailed", "Unit": "Count"},
                    {"Name": "DurationMs", "Unit": "Milliseconds"}
                ]
            }]
        },
        # Dimension values + metric values + extra searchable context
        "Pipeline": pipeline,
        "Env": "prod",
        "RowsProcessed": rows_processed,
        "RowsFailed": rows_failed,
        "DurationMs": duration_ms,
        "batchId": "b-20260702-014"
    }
    print(json.dumps(emf))  # stdout in Lambda goes to CloudWatch Logs

def handler(event, context):
    # ... do the ETL work ...
    emit_emf(pipeline="orders", rows_processed=48120, rows_failed=132, duration_ms=8123)
    return {"ok": True}
